+#!/usr/bin/env bun
+
+import { rename, unlink } from "node:fs/promises";
+import { dirname, basename, join } from "node:path";
+
+type Status = "open" | "done";
+
+interface Task {
+  id: number;
+  title: string;
+  status: Status;
+  tags: string[];
+  due?: string;
+  createdAt: string;
+  completedAt?: string;
+}
+
+interface Database {
+  version: 1;
+  nextId: number;
+  tasks: Task[];
+}
+
+const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";
+
+class CliError extends Error {}
+
+function fail(message: string): never {
+  throw new CliError(message);
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function isIsoTimestamp(value: unknown): value is string {
+  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}T/.test(value) && !Number.isNaN(Date.parse(value));
+}
+
+function isLeapYear(year: number): boolean {
+  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
+}
+
+function isDate(value: unknown): value is string {
+  if (typeof value !== "string") return false;
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+  if (!match) return false;
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+  if (month < 1 || month > 12 || day < 1) return false;
+  const monthLengths = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
+  return day <= monthLengths[month - 1];
+}
+
+function requireDate(value: string, flag: string): string {
+  if (!isDate(value)) fail(`${flag} must be a valid date in YYYY-MM-DD format`);
+  return value;
+}
+
+function normalizeTag(value: string): string {
+  return value.trim().toLowerCase();
+}
+
+function normalizeTags(value: string): string[] {
+  const tags: string[] = [];
+  const seen = new Set<string>();
+  for (const part of value.split(",")) {
+    const tag = normalizeTag(part);
+    if (tag && !seen.has(tag)) {
+      seen.add(tag);
+      tags.push(tag);
+    }
+  }
+  return tags;
+}
+
+function validateTask(value: unknown): value is Task {
+  if (!isPlainObject(value)) return false;
+  const keys = Object.keys(value);
+  const allowed = new Set(["id", "title", "status", "tags", "due", "createdAt", "completedAt"]);
+  if (keys.some((key) => !allowed.has(key))) return false;
+  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1) return false;
+  if (typeof value.title !== "string" || value.title.trim() === "") return false;
+  if (value.status !== "open" && value.status !== "done") return false;
+  if (!Array.isArray(value.tags) || value.tags.some((tag) => typeof tag !== "string" || !tag || tag !== normalizeTag(tag))) return false;
+  if (new Set(value.tags).size !== value.tags.length) return false;
+  if (value.due !== undefined && !isDate(value.due)) return false;
+  if (!isIsoTimestamp(value.createdAt)) return false;
+  if (value.status === "done" && !isIsoTimestamp(value.completedAt)) return false;
+  if (value.status === "open" && value.completedAt !== undefined) return false;
+  return true;
+}
+
+function validateDatabase(value: unknown): Database {
+  if (!isPlainObject(value) || value.version !== 1 || !Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1 || !Array.isArray(value.tasks)) {
+    fail("database is malformed");
+  }
+  if (Object.keys(value).some((key) => !["version", "nextId", "tasks"].includes(key))) fail("database is malformed");
+  if (!value.tasks.every(validateTask)) fail("database is malformed");
+  const ids = value.tasks.map((task) => task.id);
+  if (new Set(ids).size !== ids.length || ids.some((id) => id >= (value.nextId as number))) fail("database is malformed");
+  return value as unknown as Database;
+}
+
+async function loadDatabase(): Promise<Database> {
+  const file = Bun.file(databasePath);
+  if (!(await file.exists())) return { version: 1, nextId: 1, tasks: [] };
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(await file.text());
+  } catch {
+    fail("database is malformed");
+  }
+  return validateDatabase(parsed);
+}
+
+async function saveDatabase(database: Database): Promise<void> {
+  const directory = dirname(databasePath);
+  const temporaryPath = join(directory, `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`);
+  try {
+    await Bun.write(temporaryPath, `${JSON.stringify(database, null, 2)}\n`);
+    await rename(temporaryPath, databasePath);
+  } catch (error) {
+    try {
+      await unlink(temporaryPath);
+    } catch {}
+    throw error;
+  }
