  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function run(args: string[]): Promise<unknown> {
  const command = args[0];

  if (command === "add") {
    const flags = parseFlags(args.slice(1), { "--title": true, "--tags": true, "--due": true });
    if (flags["--title"] === undefined) fail("missing required flag: --title");
    const title = flags["--title"].trim();
    if (!title) fail("title must not be empty");
    const due = flags["--due"] === undefined ? undefined : requireDate(flags["--due"], "--due");
    const database = await loadDatabase();
    const task: Task = {
      id: database.nextId,
      title,
      status: "open",
      tags: normalizeTags(flags["--tags"] ?? ""),
      ...(due === undefined ? {} : { due }),
      createdAt: new Date().toISOString(),
    };
    database.nextId += 1;
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(args.slice(1), { "--status": true, "--tag": true, "--overdue": true });
    const status = flags["--status"];
    if (status !== undefined && status !== "open" && status !== "done") fail("--status must be open or done");
    const tag = flags["--tag"] === undefined ? undefined : normalizeTag(flags["--tag"]);
    if (tag === "") fail("--tag must not be empty");
    const overdue = flags["--overdue"] === undefined ? undefined : requireDate(flags["--overdue"], "--overdue");
    const database = await loadDatabase();
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(tag))
      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((left, right) => left.id - right.id);
  }

  if (command === "done") {
    if (args.length !== 2) fail(args.length > 2 ? `unknown argument: ${args[2]}` : "missing task ID");
    const id = parseId(args[1]);
    const database = await loadDatabase();
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (args.length !== 2) fail(args.length > 2 ? `unknown argument: ${args[2]}` : "missing task ID");
    const id = parseId(args[1]);
    const database = await loadDatabase();
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (args.length !== 1) fail(`unknown argument: ${args[1]}`);
    const database = await loadDatabase();
    const today = localToday();
    const open = database.tasks.filter((task) => task.status === "open").length;
    const done = database.tasks.length - open;
    const overdue = database.tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length;
    return { total: database.tasks.length, open, done, overdue };
  }

  fail(command === undefined ? "missing command" : `unknown command: ${command}`);
}

try {
  const result = await run(Bun.argv.slice(2));
  console.log(JSON.stringify(result));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.log(JSON.stringify({ error: message }));
  console.error(message);
  process.exitCode = 1;
}

