    const title = flags.get("--title")?.trim();
    if (!title) throw new CliError("--title is required and must not be empty");
    const due = flags.get("--due");
    if (due !== undefined && !isDate(due)) throw new CliError("--due must be a valid YYYY-MM-DD date");
    const database = await loadDatabase();
    const task: Task = {
      id: database.nextId++, title, status: "open", tags: normalizeTags(flags.get("--tags")), createdAt: new Date().toISOString(),
      ...(due === undefined ? {} : { due }),
