  const options: ParsedOptions = {};
  for (let index = 0; index < args.length; index++) {
    const flag = args[index];
    if (!flag.startsWith("--") || !allowed.has(flag)) fail(`Unknown flag: ${flag}`);
    if (options[flag] !== undefined) fail(`Duplicate flag: ${flag}`);
