  const id = Number(args[0]);
  if (!Number.isSafeInteger(id)) fail("Expected a positive integer task ID");
  return id;
}

function normalizeTags(input: string | undefined): string[] {
  if (input === undefined) return [];
  return [...new Set(input.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
}

function taskById(database: Database, id: number): Task {
  const task = database.tasks.find((candidate) => candidate.id === id);
  if (!task) fail(`Task ${id} not found`);
  return task;
}

async function execute(args: string[]): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("Missing command");

  if (command === "add") {
    const options = parseOptions(rest, new Set(["--title", "--tags", "--due"]), new Set(["--title"]));
    const title = options["--title"].trim();
    if (!title) fail("Title must not be empty");
    const due = options["--due"];
    if (due !== undefined && !validDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
