    if (rest.length) fail(`Unknown flag: ${rest[0]}`);
    const database = await loadDatabase();
    const now = new Date();
    const today = `${now.getFullYear().toString().padStart(4, "0")}-${(now.getMonth() + 1).toString().padStart(2, "0")}-${now.getDate().toString().padStart(2, "0")}`;
